(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const canvas = $('gameCanvas'), ctx = canvas.getContext('2d'), mini = $('miniMap'), mctx = mini.getContext('2d');
  const vehicles = [
    {name:'UAZ 469',year:'1978',tag:'469 EXPEDITION',sub:'4×4 · 2.5L PETROL',class:'LIGHT SCOUT',desc:'Nimble, simple, and easy to recover. The classic forest-track tool.',power:75,weight:1.7,range:240,fuel:88,traction:1,body:'#78815d',type:'scout'},
    {name:'UAZ-452',year:'1985',tag:'452 FIELD VAN',sub:'4×4 · MOBILE WORKSHOP',class:'FIELD VAN',desc:'Forward-control van with room for tools. Front-heavy, but ready to repair.',power:76,weight:2.1,range:310,fuel:90,traction:.91,body:'#b1aa83',type:'van'},
    {name:'LuAZ-969M',year:'1982',tag:'969M SWAMP RUNNER',sub:'4×4 · AIR-COOLED',class:'SWAMP RUNNER',desc:'Featherweight and low-pressure. Floats over muskeg; not built for speed.',power:40,weight:1.2,range:180,fuel:45,traction:1.16,body:'#b69e65',type:'luaz'},
    {name:'UAZ Patriot',year:'2016',tag:'PATRIOT PICKUP',sub:'4×4 · EFI PETROL',class:'EXPEDITION',desc:'Long-wheelbase comfort, modern injection, and a balanced cargo bed.',power:135,weight:2.2,range:480,fuel:68,traction:.98,body:'#667b64',type:'pickup'},
    {name:'GAZ-66',year:'1974',tag:'66 SHISHIGA',sub:'6×6 · 4.3L V8',class:'HEAVY HAULER',desc:'Portal axles and six driven wheels. Huge appetite, huge determination.',power:115,weight:3.5,range:350,fuel:105,traction:1.28,body:'#788367',type:'truck'}
  ];
  const upgradeDefs = [
    ['⚙','Portal axles','+ ground clearance · military reduction hubs',180],['◉','Air lockers','Selectable front & rear differentials',140],['⌁','Crawler transfer case','Twin-stick · low range 4.0:1',160],['▥','Mud-terrain tires','Deep lugs · reinforced sidewalls',110],['◌','Beadlock rims','Retain tire bead below 1 bar',90],['↗','Snorkel & sealed ignition','Raise engine intake · water protection',130],['▤','Radiator & twin fans','Mud-resistant cooling package',100],['⌂','Recovery winch','18 m cable · variable pull',120],['▥','Skid plates & sliders','Protect gearbox, sump, and sills',100],['ϟ','Dual battery system','High-amp alternator · winch reserve',100]
  ];
  let selected=0, upgrades=new Set(), state={x:.075,y:.52,v:0,heading:0,steer:0,fuel:68,engine:96,pressure:1.4,awd:true,diff:false,low:false,started:false,paused:false,winching:false,cargo:true,damage:0,service:false}, keys={},last=performance.now(), elapsed=0, toastTimer;
  const zones=[{name:'PEAT BOG',desc:'Soft ground · deep ruts',footer:'PEAT / SOFT',traction:.48},{name:'KIVI RIVER',desc:'Current · 0.6 m depth',footer:'RIVER / CURRENT',traction:.72},{name:'FROZEN MUSKEG',desc:'Crust over soft peat',footer:'MUSKEG / FROZEN',traction:.56},{name:'GRAVEL TRACK',desc:'Loose stone · firm base',footer:'GRAVEL / LOOSE',traction:.88},{name:'VYSOKY RIDGE',desc:'Rock · slick exposed stone',footer:'ROCK / SLICK',traction:.74}];
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function showToast(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,r.width*d);canvas.height=Math.max(1,r.height*d);ctx.setTransform(d,0,0,d,0,0);draw()}
  function terrainAt(t){if(t<.21)return 0;if(t<.39)return 1;if(t<.57)return 2;if(t<.77)return 3;return 4}
  function initMap(){let w=mini.width,h=mini.height;mctx.fillStyle='#28382b';mctx.fillRect(0,0,w,h);for(let i=0;i<38;i++){let x=(i*67)%w,y=(i*41)%h;mctx.fillStyle=i%2?'#344630':'#2e402f';mctx.beginPath();mctx.arc(x,y,4+(i%4)*2,0,Math.PI*2);mctx.fill()}mctx.fillStyle='#46645b';mctx.beginPath();mctx.moveTo(w*.37,0);mctx.bezierCurveTo(w*.53,h*.24,w*.24,h*.51,w*.52,h);mctx.lineTo(w*.62,h);mctx.bezierCurveTo(w*.36,h*.51,w*.65,h*.27,w*.42,0);mctx.fill();mctx.setLineDash([5,4]);mctx.strokeStyle='#cde581';mctx.lineWidth=2;mctx.beginPath();mctx.moveTo(w*.11,h*.52);mctx.bezierCurveTo(w*.3,h*.55,w*.37,h*.39,w*.48,h*.51);mctx.bezierCurveTo(w*.62,h*.67,w*.72,h*.33,w*.9,h*.28);mctx.stroke();mctx.setLineDash([]);mctx.fillStyle='#eef2dc';mctx.font='8px monospace';mctx.fillText('VYSOKY',w*.72,h*.16)}
  function terrainDraw(w,h){let g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#506247');g.addColorStop(.5,'#394b38');g.addColorStop(1,'#667354');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
    // soft forest floor mottling
    for(let i=0;i<260;i++){let x=(i*139.37%w),y=(i*91.73%h),r=8+(i*17%36);ctx.fillStyle=['#a2a1760a','#111c1450','#c5b98c09','#273c2a42'][i%4];ctx.beginPath();ctx.ellipse(x,y,r,r*.44,i*.8,0,Math.PI*2);ctx.fill()}
    // forest silhouette stands
    for(let i=0;i<92;i++){let x=(i*97.3%w),y=(i*67.1%h),sz=10+(i*13%19);if(Math.abs(y-h*.52)<h*.18&&x<w*.8)continue;tree(x,y,sz,i)}
    // bog patches
    ctx.fillStyle='#342d21aa';ctx.beginPath();ctx.ellipse(w*.17,h*.48,w*.22,h*.3,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#62533a77';ctx.beginPath();ctx.ellipse(w*.22,h*.42,w*.14,h*.12,-.2,0,Math.PI*2);ctx.fill();
    // crossing current
    ctx.fillStyle='#4b77737e';ctx.beginPath();ctx.moveTo(w*.49,0);ctx.bezierCurveTo(w*.64,h*.23,w*.38,h*.46,w*.59,h*.62);ctx.bezierCurveTo(w*.72,h*.78,w*.44,h*.86,w*.57,h);ctx.lineTo(w*.72,h);ctx.bezierCurveTo(w*.58,h*.8,w*.84,h*.72,w*.67,h*.57);ctx.bezierCurveTo(w*.48,h*.4,w*.78,h*.24,w*.61,0);ctx.fill();
    ctx.strokeStyle='#b9cec04c';ctx.lineWidth=2;for(let i=0;i<9;i++){let yy=(i*37+elapsed*4)%h,xx=w*(.52+(i%3)*.035);ctx.beginPath();ctx.moveTo(xx,yy);ctx.quadraticCurveTo(xx+15,yy+4,xx+29,yy);ctx.stroke()}
    // rocky ridge
    ctx.fillStyle='#777b68';ctx.beginPath();ctx.moveTo(w*.78,0);ctx.lineTo(w,h*.01);ctx.lineTo(w,h*.34);ctx.lineTo(w*.77,h*.3);ctx.lineTo(w*.71,h*.24);ctx.fill();ctx.fillStyle='#9a9982';for(let i=0;i<20;i++){let x=w*(.76+(i*17%24)/100),y=h*(.02+(i*29%25)/100);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+10,y-5);ctx.lineTo(x+17,y+5);ctx.lineTo(x+4,y+7);ctx.fill()}
    // two-track path
    ctx.lineCap='round';ctx.strokeStyle='#766447';ctx.lineWidth=Math.max(25,w*.045);ctx.beginPath();ctx.moveTo(w*.05,h*.56);ctx.bezierCurveTo(w*.25,h*.5,w*.31,h*.58,w*.43,h*.53);ctx.bezierCurveTo(w*.58,h*.43,w*.65,h*.57,w*.72,h*.43);ctx.bezierCurveTo(w*.82,h*.34,w*.85,h*.3,w*.98,h*.26);ctx.stroke();ctx.strokeStyle='#988566';ctx.lineWidth=Math.max(12,w*.024);ctx.stroke();ctx.setLineDash([5,9]);ctx.strokeStyle='#d2c49b77';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.05,h*.56);ctx.bezierCurveTo(w*.25,h*.5,w*.31,h*.58,w*.43,h*.53);ctx.bezierCurveTo(w*.58,h*.43,w*.65,h*.57,w*.72,h*.43);ctx.bezierCurveTo(w*.82,h*.34,w*.85,h*.3,w*.98,h*.26);ctx.stroke();ctx.setLineDash([]);
    // rut lines across bog and path tracks
    ctx.strokeStyle='#29261b77';ctx.lineWidth=3;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(w*(.06+i*.013),h*.51);ctx.bezierCurveTo(w*.23,h*(.45+i*.016),w*.29,h*(.55+i*.01),w*.44,h*(.5+i*.008));ctx.stroke()}
    // marker labels drawn in DOM
    // trees foreground along edges
  }
  function tree(x,y,s,i){ctx.fillStyle='#14241ab0';ctx.beginPath();ctx.ellipse(x+3,y+5,s*.8,s*.42,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=i%3?'#1f3826':'#2b442b';ctx.beginPath();ctx.moveTo(x,y-s);ctx.lineTo(x-s*.72,y+s*.42);ctx.lineTo(x+s*.72,y+s*.42);ctx.closePath();ctx.fill();ctx.fillStyle='#455a35';ctx.beginPath();ctx.moveTo(x,y-s*.72);ctx.lineTo(x-s*.48,y+s*.18);ctx.lineTo(x+s*.47,y+s*.18);ctx.closePath();ctx.fill();ctx.fillStyle='#60513c';ctx.fillRect(x-1,y+s*.26,3,s*.35)}
  function drawTruck(x,y,scale,angle,vehicle){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale,scale);ctx.fillStyle='#10130f';ctx.beginPath();ctx.ellipse(0,10,26,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#171c18';for(let dx of [-13,13])for(let dy of [-13,13]){ctx.beginPath();ctx.ellipse(dx,dy,5,8,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#777c6b';ctx.lineWidth=1;ctx.stroke()}ctx.fillStyle=vehicle.body;ctx.strokeStyle='#c5c6a2';ctx.lineWidth=.8;ctx.beginPath();ctx.roundRect(-20,-14,40,28,4);ctx.fill();ctx.stroke();ctx.fillStyle='#303d34';ctx.beginPath();ctx.roundRect(-10,-11,19,21,3);ctx.fill();ctx.fillStyle='#879081';ctx.fillRect(-8,-9,7,17);ctx.fillRect(1,-9,6,17);ctx.fillStyle='#e3d995';ctx.fillRect(17,-9,3,6);ctx.fillStyle='#262e27';ctx.fillRect(-23,-4,4,9);if(state.cargo){ctx.fillStyle='#9d865a';ctx.fillRect(-15,-27,14,9);ctx.strokeStyle='#d0b879';ctx.strokeRect(-15,-27,14,9)}ctx.restore()}
  function draw(){if(!ctx||!canvas.width)return;const d=Math.min(devicePixelRatio||1,2),w=canvas.width/d,h=canvas.height/d;ctx.clearRect(0,0,w,h);terrainDraw(w,h);let truckX=w*(.09+state.x*.81),truckY=h*(.56+(state.y-.5)*.11);let sc=clamp(w/690,.7,1.3);drawTruck(truckX,truckY,sc,state.heading,vehicles[selected]);if(state.winching){ctx.strokeStyle='#d6e989';ctx.lineWidth=1;ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(truckX,truckY);ctx.lineTo(Math.min(w-20,truckX+75),truckY-80);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#d6e989';ctx.beginPath();ctx.arc(Math.min(w-20,truckX+75),truckY-80,5,0,7);ctx.fill()}if(state.started&&!state.paused){ctx.fillStyle='#d9e3ce0b';ctx.fillRect(0,0,w,h)}updateMini()}
  function updateMini(){const w=mini.width,h=mini.height;let x=w*(.11+state.x*.79),y=h*(.52+(state.y-.5)*.13);mctx.fillStyle='#e4eea0';mctx.beginPath();mctx.arc(x,y,4,0,7);mctx.fill();mctx.strokeStyle='#e4eea080';mctx.beginPath();mctx.moveTo(x,y);mctx.lineTo(x+Math.cos(state.heading)*9,y+Math.sin(state.heading)*9);mctx.stroke()}
  function setVehicle(index){selected=index;let v=vehicles[index];$('vehicleName').innerHTML=`${v.name} <span>· ${v.year}</span>`;$('vehicleNameTag').textContent=v.tag;$('vehicleTagSub').textContent=v.sub;$('rangeValue').innerHTML=`${v.range} <i>km</i>`;state.fuel=v.fuel*.77;$('fuelText').innerHTML=`${Math.round(state.fuel/v.fuel*100)}<span>%</span>`;renderFleet();draw()}
  function renderFleet(){let grid=$('fleetGrid');grid.innerHTML='';vehicles.forEach((v,i)=>{let card=document.createElement('article');card.className='fleet-card'+(i===selected?' selected':'');card.innerHTML=`<div class="fleet-art"><svg viewBox="0 0 180 72"><ellipse cx="90" cy="61" rx="64" ry="6" fill="#0e130f" opacity=".7"/><path d="M22 49 32 30q2-6 10-7l68-2q8 0 14 6l21 17 20 4 4 10H20z" fill="${v.body}"/><path d="m48 27 59-2q7 0 12 6l13 13H40z" fill="#34443b"/><path d="M28 52h137v6H28z" fill="#3e453a"/><circle cx="52" cy="56" r="11" fill="#111613"/><circle cx="130" cy="56" r="11" fill="#111613"/><circle cx="52" cy="56" r="5" fill="#929282"/><circle cx="130" cy="56" r="5" fill="#929282"/></svg></div><h3>${v.name} <span style="color:#899588;font-weight:400">· ${v.year}</span></h3><p>${v.desc}</p><span class="fleet-class">${v.class}</span><div class="fleet-stats"><span>${v.power} HP</span><span>${v.weight} T</span><span>${v.range} KM</span></div>`;card.onclick=()=>{setVehicle(i);showToast(`${v.name} selected · setup applied`)};grid.append(card)})}
  function renderUpgrades(){let g=$('upgradeGrid');g.innerHTML='';upgradeDefs.forEach(([icon,name,desc,cost],i)=>{let owned=upgrades.has(i),card=document.createElement('div');card.className='upgrade-card';card.innerHTML=`<span class="upgrade-icon">${icon}</span><div><b>${name}</b><small>${desc}</small></div><button class="${owned?'owned':''}" data-i="${i}">${owned?'INSTALLED':`₽ ${cost} · FIT`}</button>`;card.querySelector('button').onclick=()=>{if(!owned){upgrades.add(i);if(i===0)showToast('Portal axles installed · clearance +12 cm');else if(i===1)showToast('Air lockers installed · traction improved');else if(i===3)showToast('Mud tires installed · bog traction improved');else if(i===5)showToast('Snorkel installed · water protection on');else showToast(`${name} installed`);renderUpgrades()}};g.append(card)})}
  function openGarage(){ $('garageModal').classList.remove('hidden');$('pauseOverlay').classList.add('hidden');renderFleet();renderUpgrades() }
  function closeGarage(){ $('garageModal').classList.add('hidden');if(state.started&&state.paused){state.paused=false;$('pauseOverlay').classList.add('hidden')}}
  function setToggle(id,key){state[key]=!state[key];$(id).classList.toggle('active',state[key]);showToast(`${key==='awd'?'All-wheel drive':key==='diff'?'Differential lock':'Low range'} ${state[key]?'engaged':'disengaged'}`)}
  function movePressure(d){state.pressure=clamp(Math.round((state.pressure+d)*10)/10,.5,2.4);$('pressureSlider').value=state.pressure;$('pressureValue').textContent=state.pressure.toFixed(1);showToast(`CTIS pressure · ${state.pressure.toFixed(1)} bar`)}
  function start(){state.started=true;state.paused=false;$('startOverlay').classList.add('dismissed');$('statusText').textContent='EXPEDITION IN PROGRESS';showToast('Expedition started · watch your tire pressure')}
  function pause(){if(!state.started)return;state.paused=!state.paused;$('pauseOverlay').classList.toggle('hidden',!state.paused)}
  function active(key){return !!keys[key]}
  function tick(now){let dt=Math.min(.05,(now-last)/1000);last=now;if(state.started&&!state.paused){elapsed+=dt;let throttle=(active('w')||active('arrowup')?1:0)-(active('s')||active('arrowdown')?1:0),steer=(active('a')||active('arrowleft')?-1:0)+(active('d')||active('arrowright')?1:0);if(state.winching)throttle=Math.max(throttle,.7);let zone=terrainAt(state.x),v=vehicles[selected],z=zones[zone];let pressureFactor=zone===0?clamp(1.38-state.pressure*.28,.62,1.32):zone===1?clamp(1.18-state.pressure*.12,.72,1.1):clamp(.94+(state.pressure-1.3)*.08,.82,1.04);let traction=z.traction*v.traction*pressureFactor*(state.awd?1.15:.72)*(state.diff?1.17:1)*(state.low?1.08:1);let resistance=zone===0?.34:zone===1?.26:zone===2?.29:zone===3?.15:.19;let accel=.19*throttle*traction-(state.v*resistance)-(!throttle?state.v*.22:0);if(active(' ')||active('space'))accel-=state.v*.9;state.v=clamp(state.v+accel*dt,-.28,.72);let max=.72*(state.low?.48:1)*(state.fuel<=0?0:1);state.v=clamp(state.v,-.28,max);state.steer+=(steer-state.steer)*Math.min(1,dt*5);state.heading+=state.steer*state.v*dt*1.45;state.x=clamp(state.x+Math.cos(state.heading)*state.v*dt*.061,0,.98);state.y=clamp(state.y+Math.sin(state.heading)*state.v*dt*.13,.20,.8);let pct=Math.round(state.x*100);let distance=Math.max(0,2.8*(1-state.x/.98));$('progressFill').style.width=`${pct}%`;$('distanceReadout').textContent=`${(2.8*pct/100).toFixed(1)} / 2.8 km`;$('targetDistance').textContent=`${distance.toFixed(1)} km`;$('speedReadout').textContent=String(Math.round(Math.abs(state.v)*57)).padStart(2,'0');$('gearReadout').textContent=state.v>.02?(state.low?'L':'1'):state.v<-.02?'R':'N';$('terrainName').textContent=z.name;$('terrainDesc').textContent=z.desc;$('terrainFooter').textContent=z.footer;
      if(Math.abs(state.v)>.08){state.fuel=Math.max(0,state.fuel-dt*(.018+Math.abs(state.v)*.05)*(selected===4?1.35:1));state.engine=Math.max(35,state.engine-dt*(zone===1?.06:.008)*(state.v>.48?2:1));if(zone===0&&state.pressure>1.3&&Math.random()<dt*.4){state.damage=Math.min(60,state.damage+dt*.8);state.engine=Math.max(35,state.engine-dt*.3)}if(zone===1&&Math.random()<dt*.08&&!upgrades.has(5)){state.engine=Math.max(35,state.engine-dt*1.7);showToast('Water over the hood · engine taking water!')} }
      if(state.x>.96&&state.cargo){state.cargo=false;$('cargoStatus').textContent='DELIVERED';$('statusText').textContent='CONTRACT COMPLETE';showToast('Generator delivered · contract complete!');state.v=0}
      if(state.damage>30)$('tirePart').className='warn';$('fuelText').innerHTML=`${Math.round(state.fuel/vehicles[selected].fuel*100)}<span>%</span>`;$('fuelFill').style.width=`${Math.round(state.fuel/vehicles[selected].fuel*100)}%`;$('engineText').innerHTML=`${Math.round(state.engine)}<span>%</span>`;$('engineFill').style.width=`${state.engine}%`;$('simClock').textContent=`${String(8+Math.floor(elapsed/240)).padStart(2,'0')}:${String(Math.floor(elapsed/4)%60).padStart(2,'0')}`;draw()}
    requestAnimationFrame(tick)}
  // Events
  $('startBtn').addEventListener('click',start);$('pauseBtn').addEventListener('click',pause);$('resumeBtn').addEventListener('click',pause);$('garageOpen').addEventListener('click',openGarage);$('garageOpen2').addEventListener('click',openGarage);$('garageClose').addEventListener('click',closeGarage);$('garageDone').addEventListener('click',closeGarage);
  document.querySelectorAll('.garage-tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.garage-tabs button').forEach(x=>x.classList.toggle('selected',x===b));let vehiclesTab=b.dataset.tab==='vehicles';$('fleetGrid').classList.toggle('hidden',!vehiclesTab);$('upgradeGrid').classList.toggle('hidden',vehiclesTab);if(!vehiclesTab)renderUpgrades()}));
  $('awdToggle').onclick=()=>setToggle('awdToggle','awd');$('diffToggle').onclick=()=>setToggle('diffToggle','diff');$('lowToggle').onclick=()=>setToggle('lowToggle','low');$('pressureDown').onclick=()=>movePressure(-.1);$('pressureUp').onclick=()=>movePressure(.1);$('pressureSlider').oninput=e=>{state.pressure=+e.target.value;$('pressureValue').textContent=state.pressure.toFixed(1)};$('repairBtn').onclick=()=>{state.engine=100;state.damage=0;$('tirePart').className='part-ok';state.fuel=Math.min(vehicles[selected].fuel,state.fuel+25);showToast('Service complete · engine repaired, +25 L fuel')};$('winchBtn').onclick=()=>{state.winching=!state.winching;$('winchBtn').classList.toggle('active',state.winching);$('winchStatus').textContent=state.winching?'Cable tensioned · pulling':'Cable ready · 18 m';showToast(state.winching?'Winch engaged · slow pull':'Winch released')};$('routeBtn').onclick=()=>showToast('Route set · bog → river crossing → ridge relay');$('soundBtn').onclick=e=>{e.currentTarget.classList.toggle('active');showToast(e.currentTarget.classList.contains('active')?'Sound enabled':'Sound muted')};
  window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='e')setToggle('awdToggle','awd');if(k==='l')setToggle('diffToggle','diff');if(k==='r')setToggle('lowToggle','low');if(k==='c')movePressure(state.pressure<1?+.4:-.4);if(k==='q')$('winchBtn').click();if(k==='escape')pause()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>keys={});
  document.querySelectorAll('[data-control]').forEach(btn=>{const key={left:'a',right:'d',forward:'w',reverse:'s'}[btn.dataset.control];btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>keys[key]=false))});
  canvas.addEventListener('pointerdown',e=>{if(!state.started){start();return}let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(y>.45){keys['w']=true;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointerup',()=>keys.w=false);canvas.addEventListener('pointercancel',()=>keys.w=false);
  $('garageModal').addEventListener('click',e=>{if(e.target===$('garageModal'))closeGarage()});window.addEventListener('resize',resize);initMap();renderFleet();resize();requestAnimationFrame(tick);
})();
